var n=`0629-koshari`;var t=`world-0629`;var a=`EG`;var r=`northern-africa`;var o=4;var s=64;var l={en:`Koshari`,ua:`Кошарі`};var g={en:`Koshari is a Egypt classic prepared with green lentils, white rice, macaroni, yellow onion. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Кошарі, страва кухні країни Єгипет зі складниками: зелена сочевиця, білий рис, макарони, жовта цибуля. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var m=[{en:`Cook the listed ingredients in simmering water for about 23 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 23 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:23,i:[[`green-lentils`,200,`g`],[`water`,850,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 12 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 12 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:12,i:[[`white-rice`,230,`g`],[`water`,400,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 10 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 10 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:10,i:[[`macaroni`,200,`g`]]},{en:`Cook a garlicky tomato-vinegar sauce, keeping it distinct from the plain cooked rice, pasta and lentils.`,ua:`Приготуйте часниковий томатно-оцтовий соус окремо від варених рису, макаронів і сочевиці.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,240,`g`],[`extra-virgin-olive-oil`,65,`ml`],[`garlic`,4,`clove`],[`tomato`,520,`g`],[`tomato-paste`,50,`g`],[`white-vinegar`,30,`ml`]]},{en:`Layer lentils, rice and pasta, top with warm chickpeas and tomato sauce; crisp fried onions are a traditional accompaniment if prepared separately.`,ua:`Викладіть шарами сочевицю, рис і макарони, додайте теплий нут і томатний соус; окремо смажена хрустка цибуля, традиційне доповнення.`,t:[`layered-assembly`,`garnishing`],m:7,i:[[`canned-chickpeas`,230,`g`],[`ground-cumin`,4,`g`]]}];var c={slug:n,id:t,country:`EG`,region:r,servings:4,minutes:64,title:l,text:g,steps:m};export{a as country,c as default,t as id,s as minutes,r as region,o as servings,n as slug,m as steps,g as text,l as title};